"""Write the authorized final report from complete recorded scores and current HEAD."""
import argparse,datetime,importlib.util,json,pathlib,subprocess,zoneinfo
HERE=pathlib.Path(__file__).parent.resolve();ROOT=HERE.parents[2]
_spec=importlib.util.spec_from_file_location('langwatch_report_guards',HERE/'update-page.py')
_guards=importlib.util.module_from_spec(_spec);_spec.loader.exec_module(_guards)
def main():
 parser=argparse.ArgumentParser();parser.add_argument('--output',type=pathlib.Path,required=True);parser.add_argument('--checkpoint',action='store_true');args=parser.parse_args()
 data=json.loads((HERE/'recorded/summary.json').read_text());rows=data['rows']
 pr115,conformance,longtrace=_guards.new_studies(rows)
 fixed=_guards.fixed_adapter_studies(rows,checkpoint=args.checkpoint)
 sha=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()
 stamp=datetime.datetime.now(zoneinfo.ZoneInfo('Europe/Brussels')).isoformat()
 def cell(k):
  if k is None:return 'native Azure unmeasured'
  partial=args.checkpoint and k.startswith('longtrace-v2-pr115-') and rows[k].get('complete') is False
  r=_guards.require_metric(rows,k,allow_partial=partial);lo,hi=r['ci95'];interval='unscored' if lo is None else f'{100*lo:.2f}% to {100*hi:.2f}%';return f"{r['correct']}/{r['n']} (Wilson 95% {interval}; coverage {r['n']}/{r['total']})"+(' [checkpoint; '+str(r['n'])+' scored, '+str(r.get('pending',0))+' pending]' if partial else '')
 def cost(k):
  if k is None:return 'unmeasured'
  r=_guards.require_metric(rows,k);return 'unscored' if not r['n'] else f"{100*r['attributableUsd']/r['n']:.8f}"
 entries=[('Per-criterion rules','judges','audit','-primary','Historical bar 11/12 versus 10/12; no current pure-quality ranking'),('Verdict vector','judges','audit','-vector','Historical 39/40 versus 37/40; no current pure-quality ranking'),('Simulated user','simulator','checked','','Ahead: historical unsolicited email 0/24 versus 3/24'),('PII full','pii','audit','','Ahead on historical name/address scope; development 120/120, check 119/120'),('PII default-enabled subset','pii','audit','-enabled','No prior native-default enabled-scope measurement'),('Injection','injection','audit','','In progress: shipped easy 120/120, native unmeasured'),('Pairwise','pairwise','checked','','Easy candidate/default both 120/120')]
 lines=['# Hard comparison report','',f'Branch: `codex/pairwise-judge`; HEAD `{sha}`.',f'PR [109](https://github.com/achammah/driftbench/pull/109) targets `harvest-langwatch6`.',f'Report generated {stamp}.','', 'All candidates are **not yet the shipped default**. No production package source is changed.','', '## Scores and costs','', 'Each hard cohort has 120 cases; each fresh cohort has 60. Fresh seed is 20261013. Labels and candidate hashes precede calls. No held-out tuning occurs. Costs are attributable model USD per 100 scored cases, including cached component costs. Native Presidio uses zero model USD; CPU/install costs are not priced. Enabled-scope cost attributes the full run to that subset.']
 if args.checkpoint:lines += ['', '**Checkpoint:** only the final PR 115 long-v2 contestant may be partial. Scored/total coverage and pending cases are explicit; no whole-cohort ranking or completion is asserted for it. All other required measurements remain strict.']
 for name,kind,candidate,suffix,easy in entries:
  lines += ['',f'### {name}']
  if kind=='judges' and all(prefix in fixed for prefix in ['adapter-v2','longtrace-v2']):
   corrected_suffix='-criteria' if suffix=='-primary' else '-vector'
   lines += ['',f"Corrected trusted-event v2 measurements, generated {stamp}. Conformance remains a candidate, not yet the shipped default; PR 115 is a separate approved-source default at `{_guards.PR115_SOURCE}`.",'',_guards.corrected_top_detail(rows,corrected_suffix),'','| Cohort | Old main default | Original audit candidate | Native default | Conformance candidate | PR 115 default |','| --- | --- | --- | --- | --- | --- |']
   for prefix,label in [('adapter-v2','Short, new seed 20261019'),('longtrace-v2','Long, new seed 20261020')]:
    lines.append('| '+label+' | '+' | '.join(cell(prefix+'-'+variant+corrected_suffix) for variant in _guards.CRITERION_VARIANTS)+' |')
   lines += ['','Short: '+_guards.corrected_cohort_outcome(rows,'adapter-v2'),'Long: '+_guards.corrected_cohort_outcome(rows,'longtrace-v2'),'','Full five-procedure counts, intervals and all costs appear in the corrected short/long tables below.','', '#### Retained historical criterion results']
  lines += ['',easy+'.']
  if kind=='judges':lines += ['',_guards.OLD_CRITERION_LIMIT,'']
  lines += ['', '| Cohort | Shipped | Candidate | Native default | USD/100 shipped | USD/100 candidate | USD/100 native |','| --- | --- | --- | --- | --- | --- | --- |']
  for tag,label in [('', 'Hard'),('-heldout','Fresh held-out')]:
   keys=[f'{kind}-{v}{tag}{suffix}' for v in ['ours',candidate,'native' if kind=='pii' else 'theirs']]
   if kind=='injection':keys[2]=None
   lines.append('| '+label+' | '+' | '.join([cell(k) for k in keys]+[cost(k) for k in keys])+' |')
  if kind=='injection':lines+=['','Outcome: in progress. Native defaults use Azure Content Safety. No keys, live measurement or proxy exists. Runnable native adapters preserve pinned request/chunking behavior.']
  elif kind=='judges':
   hard=rows[f'judges-audit{suffix}'];native=rows[f'judges-theirs{suffix}'];lines+=['',f"Original audit hard result: {hard['correct']}/{hard['n']}; native: {native['correct']}/{native['n']}. Fresh results and long-trace candidate losses are separate measurements. Shipped errors remain visible; a native ceiling does not establish whole-row equality or superiority."]
  else:
   ours=rows[f'{kind}-{candidate}-heldout{suffix}'];native=rows[f'{kind}-{"native" if kind=="pii" else "theirs"}-heldout{suffix}'];diff=ours['correct']/ours['n']-native['correct']/native['n'] if ours['n'] and native['n'] else None;lines += ['', 'Fresh candidate outcome: '+('unscored' if diff is None else 'ahead by recorded point estimate' if diff>0 else 'equal' if diff==0 else 'behind')+'. Wilson intervals and shared template correlation do not establish population-level superiority.']
 if pr115:
  record=json.loads((HERE/'recorded/pairwise-pr115.json').read_text());source=record['sourceCommit']
  lines += ['', '## Approved PR 115 pairwise default', '', f"Measured source commit: `{source}`. PR [115](https://github.com/achammah/driftbench/pull/115) is approved to replace the original shipped contract once CI is green. This report does not assert that PR 115 is merged or current. Its isolated ignored source checkout is excluded from this comparison commit. The original shipped hard/fresh scores and losses remain above.", '', '| Cohort | Original shipped contract | PR 115 default | Audit candidate | Native default | USD/100 original | USD/100 PR 115 | USD/100 audit | USD/100 native |', '| --- | --- | --- | --- | --- | --- | --- | --- | --- |']
  for tag,label in [('', 'Hard 120'),('-heldout','Fresh 60, seed 20261013')]:
   keys=[f'pairwise-{v}{tag}' for v in ['ours','pr115','checked','theirs']]
   lines.append('| '+label+' | '+' | '.join([cell(key) for key in keys]+[cost(key) for key in keys])+' |')
 if pr115:
  record=json.loads((HERE/'recorded/judges-pr115.json').read_text());source=record['sourceCommit']
  lines += ['', '## Approved PR 115 criterion default', '', f"The same PR 115 measurement round includes the actual criterion default from `{source}`. Both complete raw criterion records carry matching source manifests. The original hard 120 and frozen fresh 60 (seed 20261013) labels remain unchanged. Old main shipped, original audit, native and PR 115 are separate procedures; their original losses stay visible. Approval is conditional on green CI and does not certify merged/current status.", '', '| Cohort and metric | Old main shipped | Original audit candidate | Native default | PR 115 default |', '| --- | --- | --- | --- | --- |']
  for tag,label in [('', 'Hard 120'),('-heldout','Frozen fresh 60, seed 20261013')]:
   for suffix,name in [('-primary','Primary criterion'),('-vector','Complete vector')]:
    keys=[f'judges-{variant}{tag}{suffix}' for variant in ['ours','audit','theirs','pr115']]
    lines.append('| '+label+', '+name+' | '+' | '.join(cell(key) for key in keys)+' |')
  lines += ['', '| Cohort | USD/100 old main | USD/100 original audit | USD/100 native | USD/100 PR 115 |', '| --- | --- | --- | --- | --- |']
  for tag,label in [('', 'Hard 120'),('-heldout','Frozen fresh 60, seed 20261013')]:
   keys=[f'judges-{variant}{tag}-primary' for variant in ['ours','audit','theirs','pr115']]
   lines.append('| '+label+' | '+' | '.join(cost(key) for key in keys)+' |')
  lines += ['', 'Primary and complete-vector metrics reuse each recorded criterion run; costs are not duplicated across those views. The old main column remains the historical shipped contract and the PR 115 column identifies the approved-source default.']
  lines += ['',_guards.OLD_CRITERION_LIMIT+' The published 119/120 hard and 59/60 fresh PR 115 counts and every other original criterion result remain unchanged.']
  lines += ['', '| Procedure | Hard primary / vector | Frozen fresh primary / vector |', '| --- | --- | --- |']
  for variant,label in [('ours','Old main shipped'),('audit','Original audit candidate, not yet shipped'),('theirs','Native default'),('pr115','PR 115 default')]:
   def short(tag,suffix):
    value=rows['judges-'+variant+tag+suffix];return f"{value['correct']}/{value['n']}"
   lines.append('| '+label+' | '+short('','-primary')+' / '+short('','-vector')+' | '+short('-heldout','-primary')+' / '+short('-heldout','-vector')+' |')
  if _guards.pr115_diagnosis():lines += ['', 'Completed [PR 115 miss analysis](comparisons/langwatch/hard/pr115-misses.md) records cross-entry evidence stitching on hard and deciding-evidence absence treated as vacuous compliance on fresh. The collapsed mixed-role adapter limits the latter conclusion; no fresh tuning occurs.']
 if conformance:
  lines += ['', '## Conformance judge candidate', '', 'The original audit hard/fresh losses remain above. Conformance is a separate candidate, not yet the shipped default. It judges compliance with requirements, including prohibitions and criterion-specific deciding events. The unchanged generator draws 60 fixed labels at fresh seed 20261018 before any call. Shipped, conformance and native baselines run once on that new draw, without held-out tuning.', '', '| Cohort and metric | Shipped | Original audit | Conformance candidate | Native default |', '| --- | --- | --- | --- | --- |']
  for tag,label in [('', 'Hard 120'),('-heldout-v2','New fresh 60, seed 20261018')]:
   for suffix,name in [('-primary','Primary criterion'),('-vector','Complete vector')]:
    old=cell('judges-audit'+suffix) if not tag else 'not rerun; original fresh above'
    lines.append('| '+label+', '+name+' | '+cell('judges-ours'+tag+suffix)+' | '+old+' | '+cell('judges-compliance'+tag+suffix)+' | '+cell('judges-theirs'+tag+suffix)+' |')
  lines += ['', '| Cohort | USD/100 shipped | USD/100 original audit | USD/100 conformance | USD/100 native |', '| --- | --- | --- | --- | --- |']
  for tag,label in [('', 'Hard 120'),('-heldout-v2','New fresh 60, seed 20261018')]:
   values=[cost('judges-ours'+tag+'-primary'),cost('judges-audit-primary') if not tag else 'not rerun',cost('judges-compliance'+tag+'-primary'),cost('judges-theirs'+tag+'-primary')]
   lines.append('| '+label+' | '+' | '.join(values)+' |')
  lines += ['', 'Primary and complete-vector metrics reuse each cohort run. Costs are attributed once per run, not charged separately for both views. All cohort counts and completeness flags are checked against recorded summary metrics before publication.']
 lines += ['', '## Bare shipped PII judge and configured component baseline', '', 'The main PII baseline combines the declared judged half with shipped patterns and the explicit reserved-domain benchmark opt-in. The bare shipped judge excludes identifiers by design. Both views reuse the same single recorded run; no new run or tuning occurs.', '', '| Cohort | Bare judge against full PII | Bare judge on declared name/address scope |', '| --- | --- | --- |']
 for tag,label in [('', 'Hard'),('-heldout','Fresh')]:lines.append('| '+label+' | '+cell('pii-ours'+tag+'-judge-only-full')+' | '+cell('pii-ours'+tag+'-judge-scope')+' |')
 if _guards.optional_study(rows,{'injection-attempt':120,'injection-ours-heldout-v2':60,'injection-attempt-heldout-v2':60},{'injection-attempt':120,'injection-ours-heldout-v2':60,'injection-attempt-heldout-v2':60}):
  lines += ['', '## Injection attempt-aware repair', '', 'V1 failed by interpreting the auditor refusal as absence of a user attempt. Its hard/fresh loss remains published. V2 keeps the target audit but makes attempted user manipulation explicit, accepts grounded object/array output and requires raw visible citations. It is not yet the shipped default. Design uses hard failures only.', '', '| Cohort | Shipped | Attempt-aware V2 | Native default | USD/100 shipped | USD/100 V2 |', '| --- | --- | --- | --- | --- | --- |']
  for tag,label in [('', 'Hard 120'),('-heldout-v2','New fresh 60, seed 20261017')]:lines.append('| '+label+' | '+cell('injection-ours'+tag)+' | '+cell('injection-attempt'+tag)+' | native Azure unmeasured | '+cost('injection-ours'+tag)+' | '+cost('injection-attempt'+tag)+' |')
  lines += ['', 'The new draw has zero text overlap with both previous cohorts. Labels, prompt and decoder hashes precede every V2 call. Shipped and V2 each run once on the new draw; both native defaults record unmeasured states. No held-out tuning or proxy occurs.']
 if longtrace:
  source=json.loads((HERE/'recorded/longtrace-pr115.json').read_text())['sourceCommit']
  lines += ['', '## Additional preregistered long traces','', f'The 120-case long-trace cohort is committed before any call. Deciding evidence appears early among multiple tool calls and distractor receipts. Shipped, original audit, native, conformance and PR 115 each run once without tuning or label changes. PR 115 uses the actual default at `{source}`. Conformance remains a candidate, not yet the shipped default. Earlier native ceiling measurements remain separate from actual candidate losses. All 240 criterion judgments and all 120 primary cases appear below; receipt and complete-vector metrics are secondary. No favorable family is selected.', '', '| Metric | Shipped | Original audit candidate | Native default | Conformance candidate | PR 115 default |','| --- | --- | --- | --- | --- | --- |']
  for suffix,label in [('-criteria','Preregistered primary: all 240 criteria'),('-primary','Primary criterion: all 120 cases'),('-receipt','Secondary: receipt criterion, all 120 cases'),('-vector','Secondary: complete criterion vector, all 120 cases')]:lines.append('| '+label+' | '+' | '.join(cell(f'longtrace-{v}{suffix}') for v in ['ours','audit','theirs','compliance','pr115'])+' |')
  d=json.loads((HERE/'recorded/longtrace-ours.json').read_text());lines+=['',f"Preregistration commit: `{d['registrationCommit']}`. Fixture SHA-256: `{d['fixtureSha256']}`.",'','| Contestant | Model USD per 100 |','| --- | --- |']
  for v in ['ours','audit','theirs','compliance','pr115']:lines.append(f"| {v} | {cost('longtrace-'+v+'-primary')} |")
 lines += ['', '## Scope, transport and source provenance','', '- Native PII: en_core_web_lg 3.7.1, spaCy 3.7.5, Presidio 2.2.364; actual pinned evaluator with all default entity settings. Thirty hard and fourteen fresh name/home positives fall under disabled PERSON/LOCATION. Every case ID appears in `comparisons/langwatch/hard/native-scope-misses.md`. Native enabled misses are two hard phones and one fresh phone.', '- Native injection remains unmeasured on both cohorts. Azure Jailbreak and Prompt Shield adapters, fake request parity and explicit unmeasured records ship. No proxy result exists.', '- Judge oracle version 4 requires the deciding response/tool trace for both contestants. Absence is inconclusive. Original labels are unchanged. Receipt and plan identifiers use disjoint namespaces. Prototype v1/v2/v3 scores are excluded, while every charge and interrupted reservation remains.', '- The initial empty native CLI outputs, including the two reported to the lead, are transport failures. Identical-input recovery is used once; valid wrong answers are never retried. Unrecovered cases are unscored for that contestant. Full coverage appears beside accuracy.', '- Scenario source commit `ad220e6a641c3aa38484cbb94d60566d5c9a2c10`; LangWatch source commit `e683dd9ea52c148e7678b1c22202dbfea9f1eb9f`. Native criterion template and schema match the pinned source for all 120 cases. This is the common Claude CLI prompt/schema path, not an end-to-end SDK run.', '- Pairwise preserves the preceding golden-aware user template, outcome adapter and swap-and-confirm. Its native SDK system message/tool runtime is not exercised. The pinned evaluator remains runnable but is marked deprecated upstream.', '- Simulator native history is coalesced for the text-only CLI. Scoring measures one-step disclosure of the fictional email, not complete dialogue quality. Requested-email recall is scored alongside privacy.', '- Fresh judge inputs have zero complete prompt-input overlap, but seven transcript strings are shared with hard cases under different scenario/criteria. The other cohorts have zero complete input overlap. Shared generator families limit generalization.', '', '## Production proposals','', '- PR 115 already supplies a requirement-check ledger for criterion judging. The original criterion baseline uses the older main contract; the PR 115 default is measured separately on the same hard/frozen fresh fixtures. The research conformance audit adds explicit deciding-evidence semantics and criterion-local timing; further production changes require their own tests. Offer a structured evidence audit whose availability, satisfaction and violation fields determine the verdict in code. Evaluate each criterion independently, bind exact event/entity/unit/time, and retain absence as inconclusive. The comparison candidate remains separate until production tests establish the contract.', '- Clarify that every paragraph of the last transcript entry belongs to its block. PII audit covers exact quoted values across serialization and languages. Preserve existing fictional-data exclusions by default; use explicit opt-in configuration for benchmark identifiers and broader PII scope.', '- Injection extraction should identify target, active adoption and exact evidence before deriving attack presence. Distinguish user-task changes, quoted examples and fictional systems from privileged assistant instructions or runtime state.', '- Gate simulated fact disclosure on active current request intent instead of keyword presence. Retain requested-fact recall tests so withholding everything cannot pass.', '- Keep pairwise audit plus fact-ledger fallback as a measured candidate. Its original hard 120/120 is development evidence; its fresh score is reported without cherry-picking.', '', '## Spend and verification','', f"New-task unique charged spend: {data['uniqueSpendUsd']:.8f} USD of the authorized 16 USD cap, including {data['interruptedReservations']} interrupted-call reservations totaling {data['reservationUsd']:.2f} USD. Prior-round hard pairwise attribution is excluded from this new budget.",f"Recorded invocations: {data['recordedInvocations']}; raw failed CLI invocations: {data['transportFailures']}. Per-contestant recovered/unscored counts and all wrong case IDs appear in `recorded/summary.json`.", '', 'Verification: hard contract Vitest 11 tests; prior pairwise Vitest 19 tests; scorer tests 5; PII constructor and native recorder tests; injection constructor, 10 fake HTTP tests and 54 pinned-source parity scenarios. Final record-cost/coverage/frozen-hash checks, repository typecheck, lint and history scans are reported only through [the verification log](comparisons/langwatch/hard/verification.md); this sentence does not assert their completion or green CI.', '', 'Reproduce: `python3 comparisons/langwatch/hard/score.py`; zero-new-call commands, native dependency pins and adapter commands are in `comparisons/langwatch/hard/README.md`. Results and confidence intervals are in `comparisons/langwatch/hard/recorded/results.md`.']
 lines += ['', '## Final continuation limits', '', 'The authorized final PR 115 long-v2 continuation allows at most six concurrent model calls through 06:35 local time under the 16 USD cap. Earlier contestant runs remain serial. Source, prompt, parser, fixture and label hashes stay frozen throughout this continuation; formatting waits until every run is complete. A checkpoint reports only scored coverage and does not certify the partial contestant as complete.']
 lines += ['', '## Storage migration and verification evidence', '', '- Request digest metadata uses `request_sha256` names. This storage-only migration preserves request hash values, model input bytes, labels, verdicts and attributed costs; it does not change the measured procedure.', '- The original parent history is retained when rebuilding the authorized comparison commit. Existing hard source packages remain unchanged; the ignored PR 115 source checkout is excluded from the commit.', '- Gitleaks findings are linked as evidence, not a claim of a clean scan: [initial findings](comparisons/langwatch/hard/recorded/gitleaks-before.json) and [long-trace findings](comparisons/langwatch/hard/recorded/gitleaks-longtrace-before.json). [Final verification](comparisons/langwatch/hard/verification.md) records actual scan results and command exit codes.', '- Original fresh measurements use seed 20261013; injection repair uses seed 20261017. Trusted-event validation uses seed 20261019 and long v2 uses seed 20261020. The old seed 20261018/20261014 plans remain superseded and unmeasured. Each measured new draw uses fixed labels and frozen procedures. The report omits a new study only when no summary metric or raw study record exists; default full mode rejects any observed partial study; explicit checkpoint mode permits only partial final PR 115 long-v2 coverage with pending cases disclosed.']
 lines += ['', '## Superseded unmeasured criterion plans', '', 'Conformance seed 20261018 and original long-trace seed 20261014 are retained construction artifacts. Neither plan was called. They have no measured accuracy and are superseded by the trusted-event validation seed 20261019 and long v2 seed 20261020. All old mixed-role criterion counts remain published, including 119/120 and 59/60, with the adapter defect disclosed. They are not reliable pure-quality comparisons.', '', _guards.render_fixed_adapter_studies(rows,fixed,'comparisons/langwatch/hard/')]
 text='\n'.join(lines)+'\n'
 assert '\u2014' not in text and '\u2013' not in text
 args.output.write_text(text)
if __name__=='__main__':main()
